<?php
define('ABSPATH',__DIR__.'/');define('SBS_PLUGIN_DIR',dirname(__DIR__).'/');
class WP_Error {public $message;function __construct($c,$m,$d=null){$this->message=$m;}}
function is_wp_error($v){return $v instanceof WP_Error;}function wp_json_encode($v,$flags=0){return json_encode($v,$flags);}function sanitize_text_field($v){return strip_tags($v);}function sanitize_textarea_field($v){return strip_tags($v);}function sanitize_key($v){return preg_replace('/[^a-z0-9_-]/','',strtolower($v));}function wp_generate_uuid4(){return bin2hex(random_bytes(16));}function get_option($k,$d=null){return $GLOBALS['options'][$k]??$d;}function update_option($k,$v,$a=false){$GLOBALS['options'][$k]=$v;return true;}
class SBS_Storage {
 public static function absolute_path($a){return $a['path'];}
 public static function base_dir(){return $GLOBALS['tmp'];}
 public static function ensure_directories(){return true;}
 public static function store_bytes($b,$name,$mime,$owner,$oid,$role,$label,$meta=array()){$path=$GLOBALS['tmp'].'/'.bin2hex(random_bytes(5)).'-'.$name;file_put_contents($path,$b);return array('id'=>random_int(1,100000000),'path'=>$path,'filename'=>$name,'mime'=>$mime,'sha256'=>hash('sha256',$b),'url'=>'https://example.test/private/'.$name,'metadata_json'=>json_encode($meta));}
}
class SBS_Finishing {
 public static function error($c,$m,$s=400){return new WP_Error($c,$m);}
 public static function options($i){return array('width'=>(float)($i['width']??14),'height'=>(float)($i['height']??16));}
 public static function inspect($a,$o){$p=SBS_Storage::absolute_path($a);$s=getimagesize($p);$meta=SBS_Print_QA::metadata($p);return array('width'=>$s[0],'height'=>$s[1],'sha256'=>hash_file('sha256',$p),'warnings'=>array(),'export_metadata'=>$meta);}
}
class SBS_Finishing_Flow {public static function source($r){return $r['selected']??$r['original'];}}
class SBS_Google_Drive {public static function save_artifacts($artifacts,$workspace,$candidate,$stamp,$title,$prefix,$version,$run){$GLOBALS['exports'][]=array('artifacts'=>$artifacts,'stamp'=>$stamp,'run'=>$run);if($GLOBALS['fail_transfer']??false)return new WP_Error('injected','Injected lost transfer response');return array('id'=>'folder-'.$run,'verified'=>true,'url'=>'https://example.test/folder','register'=>array('verified'=>true,'url'=>'https://example.test/register'));}}
class SBS_OpenAI {public static $calls=0;public static function review_finishing_artwork($a,$b,$title,$o,$seams,$context){self::$calls++;return array('overall'=>'clear','summary'=>'Advisory clear','findings'=>array());}}
class Request {private $params;function __construct($p){$this->params=$p;}function get_param($k){return $this->params[$k]??null;}}
require SBS_PLUGIN_DIR.'includes/class-sbs-print-qa.php';require SBS_PLUGIN_DIR.'includes/class-sbs-final-print.php';
function check($value,$message){if(!$value){throw new Exception($message);}}function run($r,$a,$p=array()){$out=SBS_Final_Print::handle($r,new Request(array_merge(array('action'=>$a),$p)));if(is_wp_error($out)){throw new Exception($out->message);}return $out;}
$GLOBALS['tmp']=sys_get_temp_dir().'/sbs-final-test-'.bin2hex(random_bytes(6));mkdir($GLOBALS['tmp']);$GLOBALS['options']=array();
try {
 check(class_exists('Imagick'),'Imagick is required for the real image tests');
 $im=new Imagick();$im->newImage(600,800,new ImagickPixel('transparent'),'png');$draw=new ImagickDraw();$draw->setFillColor('#bf7b5b');$draw->rectangle(40,40,560,760);$im->drawImage($draw);$im->setImageDepth(8);$im->setImageFormat('png32');$source=SBS_Storage::store_bytes(SBS_Print_QA::tag_png($im->getImageBlob()),'source.png','image/png','finishing',0,'source','test');$im->clear();
 $r=array('uuid'=>'workspace-test','title'=>'TT test','original'=>$source,'selected'=>$source,'versions'=>array(),'approval'=>array('sha256'=>$source['sha256'],'at'=>'saved-stage1'),'flow'=>array());
 $r=run($r,'final_begin');$r=run($r,'final_keep');check($r['final_print']['finished']['asset']===$source,'No-finish must retain the same asset and original bytes');check($r['final_print']['finished']['finish_status']==='APPROVED_NO_ADDITIONAL_FINISH','No-finish approval status missing');check(!empty($r['final_print']['finished']['approval']),'Valid stage1 approval was not carried forward');
 $r=run($r,'final_brand',array('logo_id'=>'none'));$no_finish=$r;
 $r=run($r,'final_finish',array('preset'=>'vintage','strength'=>.5,'zones'=>array(array('x'=>.1,'y'=>.1,'w'=>.1,'h'=>.1))));$out=$r['final_print']['finished']['asset'];check($out['sha256']!==$source['sha256'],'Treatment should create a separate result');check(SBS_Final_Print::intact($source),'Source checksum changed');check(empty($r['final_print']['finished']['approval']),'Effects must not auto approve');
 $a=new Imagick($source['path']);$b=new Imagick($out['path']);check($a->getImageWidth()===$b->getImageWidth()&&$a->getImageHeight()===$b->getImageHeight(),'Dimensions changed');$a->setImageAlphaChannel(Imagick::ALPHACHANNEL_EXTRACT);$b->setImageAlphaChannel(Imagick::ALPHACHANNEL_EXTRACT);check($a->exportImagePixels(0,0,600,800,'I',Imagick::PIXEL_CHAR)===$b->exportImagePixels(0,0,600,800,'I',Imagick::PIXEL_CHAR),'Finish changed alpha');$a->clear();$b->clear();
 $m=SBS_Print_QA::metadata($out['path']);check($m['bit_depth']===8&&$m['png_color_type']===6&&$m['profile']==='srgb_icc'&&abs($m['ppi_x']-300)<1,'Print RGBA/ICC/PPI was lost');
 $r=run($r,'final_approve',array('visual_reviewed'=>true,'warnings_reviewed'=>true));check($r['final_print']['finished']['visual']['status']==='PASS','Explicit owner review missing');
 $bad=SBS_Final_Print::handle($r,new Request(array('action'=>'final_brand','logo_id'=>'missing')));check(is_wp_error($bad),'Unknown logo must fail safely');
 $r=run($r,'final_brand',array('logo_id'=>'none'));$r=run($r,'final_proofs',array('template_id'=>'generic','print_placement'=>array('x'=>.5,'y'=>.5,'width'=>1)));check(count($r['final_print']['proofs'])===4,'Expected four saved shirt colours');foreach($r['final_print']['proofs'] as $p){$d=getimagesize($p['asset']['path']);check(max($d[0],$d[1])<=1400&&$p['asset']['mime']==='image/webp','Web proof is not bounded WebP');check(!$p['measured'],'Generic proof must not claim calibration');}
 $r['final_print']['package_approval']=array('scope'=>'test');$parts=SBS_Final_Print::artifacts($r);check(!is_wp_error($parts),'Package artifact creation failed');check(count(array_unique(array_column($parts,'type')))===count($parts),'Drive resume artifact types must be unique');
 $original_f=$r['final_print'];$GLOBALS['fail_transfer']=true;$failed=SBS_Final_Print::handle($r,new Request(array('action'=>'final_export','placement_reviewed'=>true,'prefix'=>'TT')));check(is_wp_error($failed),'Injected transfer failure did not fail');$first=end($GLOBALS['exports']);$GLOBALS['fail_transfer']=false;$saved=run($r,'final_export',array('placement_reviewed'=>true,'prefix'=>'TT'));$retry=end($GLOBALS['exports']);check($first===$retry,'Retry changed transfer folder/stamp/artifact bytes after a lost response');check(!empty($saved['final_print']['archive']['verified']),'Export did not retain verified result');
 $n=$no_finish;$n['final_print']['proofs']=$r['final_print']['proofs'];$n['final_print']['package_approval']=array('scope'=>'test');$parts=SBS_Final_Print::artifacts($n);$manifest=null;foreach($parts as $p){if($p['suffix']==='studio-package-manifest.json')$manifest=json_decode(file_get_contents($p['asset']['path']),true);}check(!empty($manifest['files']['candidate-finished']['same_file']),'No-finish manifest must alias the clean file');check($manifest['files']['candidate-finished']['sha256']===$source['sha256'],'No-finish alias checksum changed');
 $li=new Imagick();$li->newImage(120,36,new ImagickPixel('transparent'),'png');$ld=new ImagickDraw();$ld->setFillColor('black');$ld->rectangle(4,4,116,32);$li->drawImage($ld);$li->setImageFormat('png32');$la=SBS_Storage::store_bytes(SBS_Print_QA::tag_png($li->getImageBlob()),'genuine-test-logo.png','image/png','finishing',0,'logo','test');$li->clear();
 $GLOBALS['options']['sbs_final_library']=array(array('id'=>'approved-signature','kind'=>'logo','archived'=>false,'signature'=>true,'asset'=>$la,'label'=>'Test signature'));
 $br=run($no_finish,'final_brand',array('logo_id'=>'approved-signature','placement'=>array('x'=>.5,'y'=>.8,'width'=>.1,'bends'=>array(array('x'=>.5,'y'=>.1)))));check($br['final_print']['branded']['asset']['sha256']!==$source['sha256'],'Branded derivative was not created');check(empty($br['final_print']['branded']['approval']),'Branding silently approved');check(SBS_Final_Print::intact($source)&&SBS_Final_Print::intact($la),'Branding changed a master');$bm=SBS_Print_QA::metadata($br['final_print']['branded']['asset']['path']);check($bm['png_color_type']===6&&$bm['profile']==='srgb_icc','Branding lost RGBA/ICC');
 check(is_wp_error(SBS_Final_Print::handle($no_finish,new Request(array('action'=>'final_brand','logo_id'=>'approved-signature','placement'=>array('x'=>0,'y'=>0,'width'=>.1))))),'Clipped logo was accepted');
 $GLOBALS['options']['sbs_final_library'][0]['signature']=false;check(is_wp_error(SBS_Final_Print::handle($no_finish,new Request(array('action'=>'final_brand','logo_id'=>'approved-signature','placement'=>array('x'=>.5,'y'=>.8,'width'=>.1,'bends'=>array(array('x'=>.5,'y'=>.1))))))),'Complex logo was allowed to curve');
 $cached=run($r,'final_check',array('vision'=>true));check(SBS_OpenAI::$calls===1,'Changed artwork visual check not called');$cached=run($cached,'final_check',array('vision'=>true));check(SBS_OpenAI::$calls===1,'Unchanged advisory result was charged again');$unchanged=run($no_finish,'final_check',array('vision'=>true));check(SBS_OpenAI::$calls===1,'No-finish identical source should reuse previous visual evidence');
 $unapproved=$no_finish;$unapproved['approval']=null;unset($unapproved['final_print']);$unapproved=run($unapproved,'final_begin');$unapproved=run($unapproved,'final_keep');check(empty($unapproved['final_print']['finished']['approval']),'Independent import silently approved');
 $changed=$r;$changed['selected']=$out;check(is_wp_error(SBS_Final_Print::handle($changed,new Request(array('action'=>'final_keep')))),'Changed input must invalidate finishing re-entry');$other=$r;$other['uuid']='another';unset($other['final_print']);$other=run($other,'final_begin');check(empty($other['final_print']['finished']),'Another workspace inherited approval');
 check(is_wp_error(SBS_Final_Print::placement(array('width'=>-1))),'Invalid logo geometry accepted');check(is_wp_error(SBS_Final_Print::geometry(array('x'=>.9,'w'=>.4))),'Out-of-bounds template accepted');
 echo "Final print: actual PNG dimensions/alpha/ICC/PPI preserved; no-op aliases; explicit approvals; immutable history; four bounded WebP proofs; unique Drive roles and byte-identical retry checkpoint; source/workspace isolation passed.\n";
} finally {foreach(glob($GLOBALS['tmp'].'/*')?:array() as $path){unlink($path);}rmdir($GLOBALS['tmp']);}
